# hypothesis: TypeIs narrows a captured parameter inside a nested function and narrows an attribute access in both branches to the guarded type and its complement, so checkers that drop the negative branch or the attribute narrowing disagree with the runtime-checked result.
from typing import TypeIs, assert_type


def is_str(val: object) -> TypeIs[str]:
    return isinstance(val, str)


class Box:
    def __init__(self, item: int | str) -> None:
        self.item = item


def outer(val: int | str) -> str:
    def inner() -> str:
        if is_str(val):
            assert_type(val, str)
            return val
        assert_type(val, int)
        return str(val + 1)
    return inner()


def describe(box: Box) -> str:
    if is_str(box.item):
        assert_type(box.item, str)
        return box.item.upper()
    assert_type(box.item, int)
    return str(box.item * 2)


print(outer('ab'))
print(outer(4))
print(describe(Box('xy')))
print(describe(Box(5)))
